let randomNum;
let attempts = 0;

do {
    randomNum = Math.floor(Math.random() * 10);
    attempts++;
    console.log(`Попытка ${attempts}: ${randomNum}`);
} while (randomNum !== 7);

console.log(`Нужное число найдено за ${attempts} попыток!`);

for (let i = 0; i < 10; i++) {
    if (i === 3) continue; // Пропустить 3
    if (i === 7) break;    // Остановиться на 7
    console.log(i); // Выведет: 0, 1, 2, 4, 5, 6
}
